/// DryRun execution completes without crash.
///
/// This is the minimal smoke test: build the DAG, run it in DryRun
/// with explicit boundary mocks, and verify it completes successfully.
#[test]
fn test_dryrun_completion() {
    if !guard_test(
        "test_dryrun_completion",
        TestClass::Unit,
        FermiCost::XS,
        &[],
        &[],
    ) {
        return;
    };
    let dag = gunbc_resolve::builder::build_dsl_graph_dag(
        "tools/bootstrap.dag",
        gunbc_resolve::BuildOpts::default(),
    )
    .expect("graph should build");
    let log = execute_dag(
        &dag,
        ExecuteConfig {
            mode: ExecutionMode::DryRun(mock_spec().to_boundary_mocks()),
            ..Default::default()
        },
    )
    .expect("DryRun execution should complete without crash");
    assert!(
        !log.entries.is_empty(),
        "execution should produce log entries"
    );
}

/// All transport executors are intercepted in DryRun.
///
/// Proves: every transport executor is interceptable; DryRun won't
/// accidentally perform real I/O.
#[test]
fn test_transport_interception() {
    if !guard_test(
        "test_transport_interception",
        TestClass::Unit,
        FermiCost::XS,
        &[],
        &[],
    ) {
        return;
    };
    let dag = gunbc_resolve::builder::build_dsl_graph_dag(
        "tools/bootstrap.dag",
        gunbc_resolve::BuildOpts::default(),
    )
    .expect("graph should build");
    let result = assert_boundary_mockable(&dag, mock_spec().to_boundary_mocks());
    assert!(
        result.is_ok(),
        "All transports should be interceptable: {:?}",
        result.error
    );
    assert!(result.boundary_nodes.iter().any(|n| n == "execute_transport_extdeps_cloud_gcp_secret_manager_gcp_SecretManager_AccessVersion"), "transport executor 'execute_transport_extdeps_cloud_gcp_secret_manager_gcp_SecretManager_AccessVersion' should be in intercepted list");
    assert!(result.boundary_nodes.iter().any(|n| n == "execute_transport_extdeps_cloud_gcp_sts_gcp_STS_Exchange"), "transport executor 'execute_transport_extdeps_cloud_gcp_sts_gcp_STS_Exchange' should be in intercepted list");
    assert!(result.boundary_nodes.iter().any(|n| n == "execute_transport_extdeps_cloud_gcp_sts_github_OIDC_GetToken"), "transport executor 'execute_transport_extdeps_cloud_gcp_sts_github_OIDC_GetToken' should be in intercepted list");
    assert!(result.boundary_nodes.iter().any(|n| n == "execute_transport_extdeps_cloud_gcp_sts_gcp_Metadata_GetIdentityToken"), "transport executor 'execute_transport_extdeps_cloud_gcp_sts_gcp_Metadata_GetIdentityToken' should be in intercepted list");
    assert!(result.boundary_nodes.iter().any(|n| n == "execute_transport_extdeps_shell_shell_Env_Get"), "transport executor 'execute_transport_extdeps_shell_shell_Env_Get' should be in intercepted list");
    assert!(
        result
            .boundary_nodes
            .iter()
            .any(|n| n == "execute_read_bootstrap"),
        "transport executor 'execute_read_bootstrap' should be in intercepted list"
    );
    assert!(
        result
            .boundary_nodes
            .iter()
            .any(|n| n == "execute_bootstrap_transport"),
        "transport executor 'execute_bootstrap_transport' should be in intercepted list"
    );
    assert!(result.boundary_nodes.iter().any(|n| n == "execute_transport_extdeps_shell_shell_Env_Get_c1"), "transport executor 'execute_transport_extdeps_shell_shell_Env_Get_c1' should be in intercepted list");
}

/// Transport behavior specs cover all core executor families.
///
/// Proves: testgen is wired to the shared transport behavior catalog
/// used to drive behavioral transport contract checks.
#[test]
fn test_transport_behavior_specs_cover_core_families() {
    if !guard_test(
        "test_transport_behavior_specs_cover_core_families",
        TestClass::Unit,
        FermiCost::XS,
        &[],
        &[],
    ) {
        return;
    };
    let specs = gunbc_ir::default_transport_behaviors();
    assert_eq!(
        specs.len(),
        6,
        "transport behavior catalog should cover tcp/http/rest/file/shell/local"
    );
    assert!(
        specs
            .iter()
            .any(|s| matches!(s.transport, gunbc_ir::TransportKind::Tcp)),
        "missing tcp transport behavior spec"
    );
    assert!(
        specs
            .iter()
            .any(|s| matches!(s.transport, gunbc_ir::TransportKind::Http)),
        "missing http transport behavior spec"
    );
    assert!(
        specs
            .iter()
            .any(|s| matches!(s.transport, gunbc_ir::TransportKind::Rest)),
        "missing rest transport behavior spec"
    );
    assert!(
        specs
            .iter()
            .any(|s| matches!(s.transport, gunbc_ir::TransportKind::File)),
        "missing file transport behavior spec"
    );
    assert!(
        specs
            .iter()
            .any(|s| matches!(s.transport, gunbc_ir::TransportKind::Shell)),
        "missing shell transport behavior spec"
    );
    let tcp = specs
        .iter()
        .find(|s| matches!(s.transport, gunbc_ir::TransportKind::Tcp))
        .expect("tcp behavior spec should exist");
    assert!(
        tcp.field_routes
            .iter()
            .any(|route| route.request_field == "read_timeout_ms"
                && route.operation == "set_read_timeout"),
        "tcp behavior spec should pin read_timeout_ms routing"
    );
    assert!(
        tcp.field_routes
            .iter()
            .any(|route| route.request_field == "write_timeout_ms"
                && route.operation == "set_write_timeout"),
        "tcp behavior spec should pin write_timeout_ms routing"
    );
    let models = gunbc_ir::default_system_models();
    let contract_specs = gunbc_ir::derive_contract_test_specs(&models);
    assert!(
        !contract_specs.is_empty(),
        "system model contract specs should derive at least one test spec"
    );
    assert!(
        contract_specs
            .iter()
            .any(|s| matches!(s.phase, gunbc_ir::UpsertPhase::Check)),
        "derived contract specs should include check-phase coverage"
    );
    let harnesses = gunbc_ir::generate_contract_test_harnesses(&contract_specs);
    assert_eq!(
        harnesses.len(),
        contract_specs.len(),
        "each contract test spec should render a harness signature"
    );
    assert!(
        harnesses.iter().all(|h| h.starts_with("fn contract_")),
        "rendered harnesses should be generated contract function signatures"
    );
}

