// These tests execute the full DAG in DryRun mode with mocked transport
// responses, verifying that pure node logic produces expected outputs.

/// Flow verification: tools-bootstrap scenario.
///
/// Builds the DAG, injects mocked transport responses via DryRun,
/// and verifies that the pure node chain produces expected terminal outputs.
#[test]
fn test_flow_tools_bootstrap() {
    if !guard_test(
        "test_flow_tools_bootstrap",
        TestClass::Unit,
        FermiCost::XS,
        &[],
        &[],
    ) {
        return;
    };
    let dag = gunbc_resolve::builder::build_dsl_graph_dag(
        "tools/bootstrap.dag",
        gunbc_resolve::BuildOpts::default(),
    )
    .expect("graph should build");
    let spec = mock_spec();
    let mocks = spec.to_boundary_mocks();
    let _log = execute_dag(
        &dag,
        ExecuteConfig {
            mode: ExecutionMode::DryRun(mocks),
            ..Default::default()
        },
    )
    .expect("DryRun execution should succeed");
}

