/// Chain test: acquire_resource_std_resources_AuthContext -> release_resource_std_resources_AuthContext (depth 2)
///
/// Non-tautological: asserts observer matchers, not baseline values.
#[test]
fn test_chain_acquire_resource_std_resources_auth_context_to_release_resource_std_resources_auth_context(
) {
    if !guard_test("test_chain_acquire_resource_std_resources_auth_context_to_release_resource_std_resources_auth_context", TestClass::Unit, FermiCost::XS, &[], &[]) {
    return;
};
    let dag = gunbc_resolve::builder::build_dsl_graph_dag(
        "tools/bootstrap.dag",
        gunbc_resolve::BuildOpts::default(),
    )
    .expect("graph should build");
    let flat = lower(&dag).expect("lower should succeed").dag;
    let spec = mock_spec();
    // Full baseline DryRun to derive window entry inputs
    let baseline = execute_dag(
        &flat,
        ExecuteConfig {
            mode: ExecutionMode::DryRun(mock_spec().to_boundary_mocks()),
            ..Default::default()
        },
    )
    .expect("baseline DryRun should succeed");
    let window = Window::from_nodes(
        &flat,
        vec![
            "acquire_resource_std_resources_AuthContext",
            "release_resource_std_resources_AuthContext",
        ],
    );
    let mut mocks = spec.to_boundary_mocks();
    apply_window_inputs(&flat, &window, &baseline, &mut mocks)
        .expect("chain entry inputs should be derivable from baseline");
    let window_dag = window_subdag(&flat, &window);
    let log = execute_dag(
        &window_dag,
        ExecuteConfig {
            mode: ExecutionMode::DryRun(mocks),
            ..Default::default()
        },
    )
    .expect("chain execution should succeed");

    // Verify observer: release_resource_std_resources_AuthContext (depth 2)
    let mut matchers = HashMap::new();
    for ex in spec
        .node_examples
        .iter()
        .filter(|e| e.node_id == "release_resource_std_resources_AuthContext")
    {
        for (port, matcher) in &ex.outputs {
            if matcher.is_chain_safe() {
                matchers.insert(
                    (
                        "release_resource_std_resources_AuthContext".to_string(),
                        port.clone(),
                    ),
                    matcher.clone(),
                );
            }
        }
    }
    for leo in spec
        .live_expected_outputs
        .iter()
        .filter(|e| e.node == "release_resource_std_resources_AuthContext")
    {
        if leo.matcher.is_chain_safe() {
            matchers.insert(
                (
                    "release_resource_std_resources_AuthContext".to_string(),
                    leo.port.clone(),
                ),
                leo.matcher.clone(),
            );
        }
    }
    assert_chain_outputs(&log, &matchers).expect("chain acquire_resource_std_resources_AuthContext -> release_resource_std_resources_AuthContext should satisfy observer matchers");
}

